import { Component, Prop } from 'vue-property-decorator';
import VueSlider from 'vue-slider-component';

/* tslint:disable:max-classes-per-file */
@Component({
    components: { /* */ },
})
export class VueSliderExtension extends VueSlider {

    @Prop({ type: [Number] })
    public zoom?: number;

    public setScale(): void {
        const rail = document.querySelector('.vue-slider-rail') as HTMLDivElement;

        const decimal = new Decimal(
            Math.floor(this.isHorizontal ? rail.offsetWidth : rail.offsetHeight),
        );
        if (this.zoom !== undefined) {
            decimal.multiply(this.zoom);
        }
        decimal.divide(100);
        this.scale = decimal.toNumber();
    }

}

type Operator = '+' | '-' | '*' | '/' | '%';

/**
 * For any precise floating point calculation
 *
 * @export
 * @class Decimal
 */
/* tslint:disable:max-classes-per-file */
class Decimal {
    public num: number;

    constructor(num: number) {
        this.num = num;
    }

    public decimal(num2: number, operator: Operator): this {
        const num1 = this.num;
        const len1 = this.getDecimalLen(num1);
        const len2 = this.getDecimalLen(num2);
        let base = 0;
        switch (operator) {
            case '+':
                base = this.getExponent(len1, len2);
                this.num = (this.safeRoundUp(num1, base) + this.safeRoundUp(num2, base)) / base;
                break;
            case '-':
                base = this.getExponent(len1, len2);
                this.num = (this.safeRoundUp(num1, base) - this.safeRoundUp(num2, base)) / base;
                break;
            case '*':
                this.num =
                    this.safeRoundUp(
                        this.safeRoundUp(num1, this.getExponent(len1)),
                        this.safeRoundUp(num2, this.getExponent(len2)),
                    ) / this.getExponent(len1 + len2);
                break;
            case '/':
                base = this.getExponent(len1, len2);
                this.num = this.safeRoundUp(num1, base) / this.safeRoundUp(num2, base);
                break;
            case '%':
                base = this.getExponent(len1, len2);
                this.num = (this.safeRoundUp(num1, base) % this.safeRoundUp(num2, base)) / base;
                break;
        }
        return this;
    }

    public plus(num2: number): any {
        return this.decimal(num2, '+');
    }

    public minus(num2: number): any {
        return this.decimal(num2, '-');
    }

    public multiply(num2: number): any {
        return this.decimal(num2, '*');
    }

    public divide(num2: number): any {
        return this.decimal(num2, '/');
    }

    public remainder(num2: number): any {
        return this.decimal(num2, '%');
    }

    public toNumber(): number {
        return this.num;
    }

    private getDecimalLen(num: number): number {
        const strArr = `${num}`.split('e');
        return (`${strArr[0]}`.split('.')[1] || '').length - (strArr[1] ? +strArr[1] : 0);
    }

    private getExponent(num1: number, num2?: number): number {
        return Math.pow(10, num2 !== undefined ? Math.max(num1, num2) : num1);
    }

    // fix: 9999999.99995 * 100000 = 999999999994.9999
    private safeRoundUp(num: number, exponent: number): number {
        return Math.round(num * exponent);
    }
}